CREATE OR REPLACE FUNCTION ECAMS.LAST_TESTCINO
(ITEMID IN VARCHAR2,ACPTNO IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT INT := 0;
   RETACPT VARCHAR2(12);

--직전 테스트요청번호 추출
BEGIN
   BEGIN
       SELECT NVL(MAX(A.CR_ACPTNO),ACPTNO)
         INTO RETACPT
         FROM CMR1010 B,CMR1000 A
        WHERE B.CR_ITEMID=ITEMID
          AND B.CR_STATUS<>'3'
          AND B.CR_PRCDATE IS NOT NULL
          AND B.CR_ACPTNO=A.CR_ACPTNO
          AND A.CR_QRYCD='03'
          AND A.CR_STATUS<>'3'
          AND A.CR_PRCDATE IS NOT NULL;
        EXCEPTION
           WHEN  NO_DATA_FOUND  Then
              RETACPT := ACPTNO;
   END;

   IF ACPTNO IS NULL OR ACPTNO = '' THEN
      RETURN RETACPT;
   ELSE
       IF RETACPT = ACPTNO THEN
          RETURN RETACPT;
       END IF;
   END IF;

   BEGIN
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR1000 C,CMR1010 B,CMR1000 A
        WHERE B.CR_ITEMID=ITEMID
          AND B.CR_STATUS<>'3'
          AND B.CR_PRCDATE IS NOT NULL
          AND B.CR_ACPTNO=A.CR_ACPTNO
          AND A.CR_QRYCD<>'03'
          AND A.CR_STATUS<>'3'
          AND A.CR_PRCDATE IS NOT NULL
          AND C.CR_ACPTNO=RETACPT
          AND A.CR_ACPTDATE>C.CR_ACPTDATE;
        EXCEPTION
           WHEN  NO_DATA_FOUND  Then
              VCNT := 1;
   END;

   IF VCNT > 1 THEN
      RETACPT := ACPTNO;
   END IF;
   RETURN RETACPT;
end;